#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr;
    long long n = strtoll(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 1) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    long long steps = 0;
    long long cur = n;
    if (cur == 1) {
        printf("n=%lld steps=%lld\n", n, steps);
        return 0;
    }
    while (1) {
        if ((cur & 1LL) == 0) {
            cur = cur / 2;
        } else {
            cur = cur * 3 + 1;
        }
        steps++;
        if (cur == 1) {
            printf("n=%lld steps=%lld\n", n, steps);
            break;
        }
        if (steps > 999999) {
            puts("STEP_LIMIT_EXCEEDED");
            break;
        }
        if (cur > 1000000000000000LL) {
            puts("OVERFLOW_GUARD");
            break;
        }
    }
    return 0;
}
